END;

CREATE OR REPLACE PROCEDURE double_value(p_in IN NUMBER, p_out OUT NUMBER) AS
BEGIN
  p_out := p_in * 2;
END;

CREATE OR REPLACE FUNCTION add_one(p_n IN NUMBER) RETURN NUMBER AS
BEGIN
  RETURN p_n + 1;
END;

CREATE OR REPLACE PACKAGE BODY math_api AS
  FUNCTION twice(n NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN n * 2;
  END;
END;

DECLARE
